operations.command:
FIND(?belief.status, ?pref.name) WHERE {
  ?person CONCEPT {type: "Person", key: "user_042"}
  ?belief BELIEF (?person, "prefers", ?pref)
  FILTER(?belief.status == "accepted")
  FILTER(CONTAINS(?pref.name, "BBQ") || CONTAINS(?pref.attributes.description, "BBQ") || CONTAINS(?pref.name, "barbecue") || CONTAINS(?pref.attributes.description, "barbecue"))
} LIMIT 10
